// Formulaires accessibles à un compte Civil : dossiers médicaux civils
// (3 Advanced, 24 Medical Release, 25 Basic, 26 Medical Update) et
// candidatures (50-55) — voir Lot 3 du plan Civil.
const CIVILIAN_ALLOWED_BBCODE_VERSIONS = [3, 24, 25, 26, 50, 51, 52, 53, 54, 55];

function sanitizeForFirebase(obj) {
  if (obj === undefined) return undefined;
  if (obj === null) return null;
  if (Array.isArray(obj)) {
    return obj.map(sanitizeForFirebase).filter(v => v !== undefined);
  }
  if (typeof obj === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(obj)) {
      const sv = sanitizeForFirebase(v);
      if (sv !== undefined) out[k] = sv;
    }
    return out;
  }
  return obj;
}

const comprehensiveSanitize = (str) => {
    if (!str) return '';
    let sanitized = str.trim().replace(/[.#$[\/ \]]+/g, '_');
    sanitized = sanitized.replace(/_{2,}/g, '_');
    sanitized = sanitized.replace(/^_+|_+$/g, '');
    return sanitized;
};

const inferCoronerRank = (coronerDetails) => {
    if (!coronerDetails) return '';
    // Check if rank exists in the details object
    if (coronerDetails.rank) return coronerDetails.rank;
    // Check if category exists (alternative field name)
    if (coronerDetails.category) return coronerDetails.category;
    // Return empty string as fallback
    return '';
};

export const useReportManagement = (
    formData,
    setFormData,
    bbCodeVersion,
    setBbCodeVersion,
    getBBCodeContent,
    getCurrentReportAuthor,
    filterFormData,
    coronerListData,
    phmcListData,
    selectOptions,
    showNotification,
    removeNotification,
    setShowEasterEggModal,
    setEasterEggType,
    sendEasterEggNotification,
    modalCloseTimer,
    versionNames,
    ER_PROTOCOL_VERSION,
    CONSULTATION_NOTES_PHMC_VERSION,
    CONSULTATION_NOTES_PBC_VERSION,
    physicianRecruitmentDetails,
    psychRecruitmentDetails,
    adminRecruitmentDetails,
    emsRecruitmentDetails,
    nurseRecruitmentDetails,
    coronerRecruitmentDetails,
    selectedAgencyGroup,
    initialFormData
) => {
    const { isCivilian, civilianProfile, isAdmin, staffName, staffProfile, hasInternalRecruitment, currentEmployee, myPatientID } = useEmployeeAuth();
    const { pbcEnabled } = useSiteConfig();

    // Qui candidate : un compte Civil, ou un EMPLOYÉ qui a obtenu le statut de recrutement interne (évolution interne).
    // Même forme dans les deux cas : { uid, patientID, email, firstName, lastName, internal }.
    const applicant = useMemo(() => {
        if (isCivilian && civilianProfile?.uid) {
            return { uid: civilianProfile.uid, patientID: civilianProfile.patientID, email: civilianProfile.email, firstName: civilianProfile.firstName, lastName: civilianProfile.lastName, internal: false };
        }
        if (hasInternalRecruitment && staffProfile && currentEmployee?.uid) {
            const [first, ...rest] = String(staffProfile.name || staffName || '').trim().split(/\s+/);
            return {
                uid: currentEmployee.uid,
                patientID: myPatientID,
                email: staffProfile.email || currentEmployee.email || '',
                firstName: staffProfile.firstName || first || '',
                lastName: staffProfile.lastName || rest.join(' '),
                internal: true,
            };
        }
        return null;
    }, [isCivilian, civilianProfile, hasInternalRecruitment, staffProfile, currentEmployee, myPatientID, staffName]);
    const [savedReports, setSavedReports] = useState([]);
    const [showSavedReports, setShowSavedReports] = useState(false);
    const [isLoadingUserReports, setIsLoadingUserReports] = useState(false);
    const [selectedUserForSavedReports, setSelectedUserForSavedReports] = useState(null);
    // Chargement d'un rapport en attente : { version, data, label }. Voir l'effet plus bas.
    const [pendingFormLoad, setPendingFormLoad] = useState(null);
    // Mode « modification de ma candidature » : { candidatUid, id, version, poste, statut } ; mémorisé dans le navigateur pour survivre à un
    // rechargement de page (voir l'effet de reprise plus bas). Effacé à l'enregistrement, à l'annulation, à la déconnexion.
    const [editingApplication, setEditingApplication] = useState(null);
    const EDIT_STORAGE_KEY = 'phmcEditingApplication';
    const forgetEditing = useCallback(() => {
        setEditingApplication(null);
        try { localStorage.removeItem(EDIT_STORAGE_KEY); } catch (error) { /* stockage indisponible : sans conséquence */ }
    }, []);
    const formLoadRefs = useRef({});
    formLoadRefs.current = { initialFormData, setFormData, showNotification, setBbCodeVersion };
    const [preselectedEmployeeType, setPreselectedEmployeeType] = useState(null);
    const pendingReportAttachmentCallback = useRef(null);
    const [reportSelectionFilter, setReportSelectionFilter] = useState(null);
    const [showPositionInfoModal, setShowPositionInfoModal] = useState(false);
    const [currentPositionInfo, setCurrentPositionInfo] = useState(null);
    // Pipeline de candidatures (Lot 6) — vue Civil "Mes candidatures".
    const [myJobApplications, setMyJobApplications] = useState([]);
    const [isLoadingJobApplications, setIsLoadingJobApplications] = useState(false);
    const [showMyJobApplications, setShowMyJobApplications] = useState(false);

    const logWebhook = async (type, payload) => {
        const logRef = ref(database, 'webhook_logs/' + Date.now());
        try {
            await set(logRef, {
                type: type,
                payload: payload,
                timestamp: Date.now()
            });
        } catch (error) {
            console.error("Error logging webhook:", error);
            Sentry.captureException(error, { extra: { context: 'logWebhook' } });
        }
    };

    // authorOverride : identité réelle sous laquelle sauvegarder (compte
    // employé connecté, ou employé choisi par un admin) — voir
    // handleSaveReportWrapper dans MainApp.js. Prend le pas sur
    // getCurrentReportAuthor(formData), qui ne reflète que le nom
    // sélectionné dans le champ coronerEmployee/phmcEmployee du formulaire
    // (ou le nom du patient pour les anciens formulaires "civils").
    // options.ownerPatientId : un administrateur qui enregistre une demande civile pour un compte patient (voir SaveAsEmployeeModal) : le rapport est alors
    // celui de CE patient (visible par lui), et non un rapport du personnel.
    async function saveReport(authorOverride, options = {}) {
        // Un compte Civil ne peut sauvegarder que ses propres dossiers médicaux
        // civils ou candidatures — pas les formulaires réservés au personnel
        // (voir Lot 3 du plan Civil). Le personnel, lui, n'a toujours pas le
        // droit de sauvegarder une candidature (bloqué plus bas).
        if (isCivilian && !CIVILIAN_ALLOWED_BBCODE_VERSIONS.includes(bbCodeVersion)) {
            const message = 'Votre compte Civil ne peut sauvegarder que des dossiers médicaux civils ou des candidatures.';
            showNotification(message, 'exclamation-circle');
            return { success: false, error: message };
        }

        let key = '';
        const bbCodeContent = getBBCodeContent();
        const currentAuthor = authorOverride || getCurrentReportAuthor(formData);

        // --- Conditions d'enregistrement (voir utils/formValidation.js) ---
        // Le personnel n'enregistre pas de candidature : seul un compte Civil le peut (garde isCivilian plus haut).
        if (getFormDefinition(bbCodeVersion)?.group === 'PHMC Recruitment' && !isCivilian) {
            return { success: false, error: 'PHMC Recruitment forms cannot be saved to Firebase.' };
        }
        // Un membre du DMEC n'enregistre pas de rapport médical de soins, ni un soignant de rapport de médecine légale :
        // les formulaires sont filtrés à l'écran, et l'enregistrement le revérifie.
        if (!getFormAccess({ isAdmin, isCivilian, staffProfile, pbcEnabled }).canAccess(bbCodeVersion)) {
            const message = pbcEnabled ? 'Votre rôle ne donne pas accès à ce formulaire : il ne peut pas être enregistré.' : 'Les formulaires de la clinique de Paleto Bay (PBC) sont désactivés : ce formulaire ne peut pas être enregistré.';
            showNotification(message, 'exclamation-circle', 7000);
            return { success: false, error: message };
        }
        if (isBillableVersion(bbCodeVersion) && staffProfile && !isAdmin && !isCivilian && !isCareStaff(staffProfile)
            && normalizePatientId(formData.patientID) !== normalizePatientId(myPatientID)) {
            const message = 'Ces dossiers médicaux ne peuvent être remplis que pour vous-même : utilisez votre propre ID patient (les frais sont à votre charge).';
            showNotification(message, 'exclamation-circle', 9000);
            return { success: false, error: message };
        }
        const validation = validateReport(bbCodeVersion, formData, { isCivilian, civilianPatientId: civilianProfile?.patientID });
        if (validation.errors.length > 0) {
            const message = formatIssues(validation.errors, { title: 'Enregistrement impossible :' });
            showNotification(message, 'exclamation-circle', 9000);
            return { success: false, error: message };
        }
        // Cas légitimes mais rares (ex. patient non identifié) : on demande confirmation.
        if (validation.warnings.length > 0 && !window.confirm(`${validation.warnings.join('\n\n')}\n\nEnregistrer quand même ?`)) {
            return { success: false, error: 'Enregistrement annulé.' };
        }

        // Dossier patient : un seul dossier initial (Basique OU Avancé), la mise à jour seulement ensuite ; un formulaire repris dans son délai de 15 minutes
        // (ou resté en brouillon) est modifié SUR PLACE ; un jeton gratuit du même formulaire est dépensé automatiquement. Voir utils/dossierCore.js.
        let dossierContext = null;
        let editingForm = null;
        let dossierToken = false;
        if (isDossierVersion(bbCodeVersion) && formData.patientID) {
            try {
                dossierContext = await loadDossierContext(formData.patientID, Date.now(), { myPatientID, staffName });
            } catch (dossierError) {
                console.warn('Dossier patient illisible, contrôles ignorés :', dossierError);
            }
            if (dossierContext) {
                const editKey = String(formData.dossierEditPath || '').split('/').pop();
                editingForm = editKey ? dossierContext.forms.find((form) => form.key === editKey) || null : null;
                if (editingForm) {
                    const allowed = canModifyForm(editingForm, {
                        role: isAdmin ? 'admin' : (isCivilian || normalizePatientId(myPatientID) === normalizePatientId(formData.patientID) ? 'patient' : 'personnel'),
                        isCreator: !!currentAuthor && String(editingForm.authorName || '').trim().toLowerCase() === String(currentAuthor).trim().toLowerCase(),
                    });
                    if (!allowed.edit) {
                        const message = 'Ce formulaire ne peut plus être modifié (le délai de 15 minutes après paiement est écoulé, ou il a été rempli par le personnel). Utilisez la « Mise à jour du dossier médical ».';
                        showNotification(message, 'exclamation-circle', 9000);
                        return { success: false, error: message };
                    }
                } else {
                    const blocked = dossierBlockMessage(bbCodeVersion, dossierContext);
                    if (blocked) {
                        showNotification(blocked, 'exclamation-circle', 10000);
                        return { success: false, error: blocked };
                    }
                    dossierToken = hasToken(dossierContext.tokens, bbCodeVersion) && computeBilling(bbCodeVersion, formData).baseAmount > 0;
                }
            }
        }

        // Le titre est fabriqué par buildReportTitle : exactement celui affiché dans
        // « Titre du Formulaire » pendant la saisie (voir MainApp).
        key = buildReportTitle(bbCodeVersion, formData, getFormDefinition(bbCodeVersion)?.name);
        // Titre « pur » (sans suffixe de doublon) : c'est celui que copie « Copier le titre ».
        const pureTitle = key;

        // If key is still empty, something went wrong (should be caught by validations)
        if (!key) {
            const message = 'Could not generate a report key. Save aborted.';
            showNotification(message, 'error');
            return { success: false, error: message };
        }

        if (!currentAuthor) {
            const message = 'Cannot determine report author. Please ensure an employee is selected or patient name is filled if applicable for this form type.';
            showNotification(message, 'error');
            return { success: false, error: message };
        }

        // Patient déclaré décédé par le DMEC : le personnel non DMEC ne peut plus rien enregistrer sur son ID (les règles Firebase le
        // refusent aussi ; ceci donne le message clair). Un admin peut toujours, et débloque la fiche si besoin.
        const writerIsDmec = isAdmin || readFamiliesOf(staffProfile).dmec;
        if (formData.patientID && !writerIsDmec && !isCivilian) {
            const deathLock = await loadDeathLock(formData.patientID);
            if (deathLock) {
                showNotification(DEATH_LOCK_MESSAGE, 'warning', 10000);
                return { success: false, error: DEATH_LOCK_MESSAGE };
            }
        }

        const sanitizedAuthorId = comprehensiveSanitize(currentAuthor);

        // Évite d'avoir plusieurs rapports affichés avec exactement le même nom
        // (ex: deux chirurgies pour le même patient le même jour) : on vérifie
        // les rapports déjà enregistrés pour cet auteur et on ajoute un
        // suffixe " (2)", " (3)"... si le nom généré existe déjà.
        try {
            const authorReportsSnapshot = editingForm ? { exists: () => false } : await get(ref(database, `savedReports/${sanitizedAuthorId}`));
            if (authorReportsSnapshot.exists()) {
                const existingKeys = new Set(
                    Object.values(authorReportsSnapshot.val()).map((r) => r.originalKey)
                );
                if (existingKeys.has(key)) {
                    let suffix = 2;
                    while (existingKeys.has(`${key} (${suffix})`)) {
                        suffix++;
                    }
                    key = `${key} (${suffix})`;
                }
            }
        } catch (error) {
            console.warn('Could not check for duplicate report names, saving without suffix:', error);
        }

        const sanitizedKey = editingForm ? editingForm.key : key.trim().replace(/[.#$[\/ \]]+/g, '_') + '_' + Date.now();

        // --- Easter Egg Logic ---
        const currentSavedCountForAuthor = savedReports.filter(r => r.authorName === currentAuthor).length;
        const easterEggAlreadyShown = localStorage.getItem('easterEggShown') === 'true';
        let showNormalEasterEgg = false;
        let showRareEasterEgg = false;

        if (currentSavedCountForAuthor === 4 && !easterEggAlreadyShown) {
            showNormalEasterEgg = true;
        } else if (currentSavedCountForAuthor > 4 && !easterEggAlreadyShown) {
            showNormalEasterEgg = Math.random() < 0.05;
        } else if (easterEggAlreadyShown) {
            showRareEasterEgg = Math.random() < 0.01;
        }

        if (showNormalEasterEgg) {
            setShowEasterEggModal(true);
            setEasterEggType('normal');
            localStorage.setItem('easterEggShown', 'true');
            sendEasterEggNotification('normal');
        } else if (showRareEasterEgg) {
            setShowEasterEggModal(true);
            setEasterEggType('rare');
            sendEasterEggNotification('rare');
        }
        // --- End Easter Egg Logic ---

        const reportDataToSave = {
        bbCodeVersion: bbCodeVersion,
        data: filterFormData(formData, bbCodeVersion),
        bbCode: bbCodeContent,
        // Un formulaire de dossier repris dans son délai garde sa date d'origine (sinon on pourrait prolonger le délai indéfiniment).
        timestamp: editingForm ? editingForm.timestamp : Date.now(),
        originalKey: key,
        title: pureTitle,
        authorName: currentAuthor,
        // Créateur réel (reste le même si le rapport est copié chez un médecin).
        creatorName: currentAuthor
        };

        // L'ID patient est conservé dans le rapport même quand le formulaire ne le
        // liste pas parmi ses champs « pertinents » (ex. rapports DMEC) : il permet de
        // retrouver le dossier et de réindexer.
        if (formData.patientID && reportDataToSave.data) {
            reportDataToSave.data.patientID = normalizePatientId(formData.patientID);
        }

        // Fallbacks anti-undefined sur les champs sensibles
        if (reportDataToSave.data && reportDataToSave.data.coronerRank === undefined) {
        reportDataToSave.data.coronerRank = null;
        }

        // Supprime toute autre clé undefined profondément
        const cleanPayload = sanitizeForFirebase(reportDataToSave);
        const reportPath = editingForm ? editingForm.reportPath : `savedReports/${sanitizedAuthorId}/${sanitizedKey}`;

        try {
            const reportRef = ref(database, reportPath);
            await set(reportRef, cleanPayload);
            showNotification(`Rapport "${key}" sauvegardé pour ${currentAuthor} (visible dans "Rapports Sauvegardés").`, 'save');

            // Regroupement par patient (Lot 5) : si le formulaire porte un ID
            // patient, on indexe ce rapport dans patientRecords/{patientID} pour
            // qu'il puisse être retrouvé/partagé/copié indépendamment de qui l'a
            // écrit. "owner" quand le civil sauvegarde son propre dossier,
            // "staff-only" quand c'est le personnel qui le remplit pour lui (pas
            // encore partagé) — voir le bouton "Partager avec le patient".
            // Best-effort : une erreur ici ne doit jamais faire échouer la
            // sauvegarde du rapport lui-même.
            if (formData.patientID) {
                let isOwnedByThisCivilian = false;
                try {
                    const ownPatientId = options.ownerPatientId || (isCivilian ? civilianProfile?.patientID : myPatientID);
                    isOwnedByThisCivilian = !!ownPatientId
                        && normalizePatientId(ownPatientId) === normalizePatientId(formData.patientID);
                    await writeIndexEntry({
                        patientID: formData.patientID,
                        indexKey: sanitizedKey,
                        entry: {
                            reportPath,
                            visibility: isOwnedByThisCivilian ? 'owner' : 'staff-only',
                            bbCodeVersion,
                            originalKey: key,
                            title: pureTitle,
                            authorName: currentAuthor,
                            creatorName: currentAuthor,
                            patientName: formData.patientName || null,
                            timestamp: editingForm ? editingForm.timestamp : Date.now(),
                            // Mise à jour de simples coordonnées : gratuite et appliquée tout de suite par le serveur ; jeton gratuit dépensé : repris pour le rendre si le formulaire est supprimé.
                            ...(Number(bbCodeVersion) === 26 && isContactOnlyUpdate(formData) ? { dossierImmediat: true } : {}),
                            ...(dossierToken ? { dossierJeton: true } : {}),
                            ...(formData.dossierSansCompte === true && !isOwnedByThisCivilian ? { dossierSansCompte: true } : {}),
                        },
                    });
                } catch (indexError) {
                    console.warn('Could not index report under patientRecords:', indexError);
                }

                // Facturation : les 4 formulaires médicaux civils payants créent une facture au nom du patient
                // (notification à sa connexion, état de paiement dans son dossier, mails groupés). Best-effort.
                try {
                    // Jeton gratuit : dépensé (compteur - 1) puis facture « sans paiement ». Formulaire de dossier repris : sa facture existe déjà (jamais réécrite).
                    if (dossierToken) dossierToken = await spendDossierToken(dossierContext.patientNode, bbCodeVersion, dossierContext.tokens);
                    if (!(editingForm && editingForm.invoice)) {
                        await recordInvoiceForReport({
                            patientID: formData.patientID,
                            indexKey: sanitizedKey,
                            reportPath,
                            bbCodeVersion,
                            title: pureTitle,
                            formData: dossierToken ? { ...formData, dossierJeton: true } : formData,
                            createdBy: currentAuthor,
                        });
                    }
                } catch (invoiceError) {
                    console.warn('Could not record patient invoice:', invoiceError);
                }
                // File du dossier patient : le serveur applique le formulaire 15 minutes après son paiement (voir utils/dossierCore.js).
                if (dossierContext && isDossierVersion(bbCodeVersion)) {
                    try {
                        await enqueueDossierForm({
                            patientNode: dossierContext.patientNode, key: sanitizedKey, version: bbCodeVersion, reportPath,
                            createdAt: editingForm ? editingForm.timestamp : reportDataToSave.timestamp, createur: isOwnedByThisCivilian ? 'patient' : 'personnel', jeton: dossierToken || !!editingForm?.jeton,
                        });
                    } catch (queueError) {
                        console.warn('Could not queue the dossier form:', queueError);
                        showNotification("Le formulaire est enregistré, mais il n'a pas pu être mis en file pour le dossier patient : prévenez un administrateur.", 'warning', 9000);
                    }
                }
                // Libération médicale : la demande part avec le formulaire. Avec des rapports retenus, chaque médecin concerné est prévenu et partage SES rapports ;
                // sans rapport précis (ou pour « Autres dossiers »), l'administration est prévenue et la traite à la main.
                if (Number(bbCodeVersion) === RELEASE_VERSION) {
                    try {
                        const own = isCivilian || !!options.ownerPatientId;
                        const created = await createReleaseRequest({
                            patientID: formData.patientID,
                            patientName: formData.patientName || [formData.patientFirstName, formData.patientMiddleName, formData.patientLastName].filter(Boolean).join(' '),
                            requester: { uid: currentEmployee?.uid || '', name: own ? (isCivilian && civilianProfile ? `${civilianProfile.firstName || ''} ${civilianProfile.lastName || ''}`.trim() : currentAuthor) : (staffName || currentAuthor), role: own ? 'patient' : 'personnel' },
                            reportPath,
                            categories: formData.MedicalRecordsRelease,
                            from: formData.StupidDateFrom,
                            to: formData.StupidDateTo,
                            selection: Array.isArray(formData.releaseReports) ? formData.releaseReports : [],
                            otherText: Array.isArray(formData.MedicalRecordsRelease) && formData.MedicalRecordsRelease.includes('Other') ? formData.MedicalRecordsReleaseOther : '',
                        });
                        if (created) {
                            const doctors = practitionerLabel(formData.releaseReports);
                            showNotification(created.manuelle && !doctors
                                ? "Demande de divulgation transmise à l'administration, qui la traitera."
                                : `Demande de divulgation transmise à : ${doctors}. Chaque médecin partage ses propres rapports avec le patient.${created.manuelle ? ' Les autres dossiers demandés sont traités par l’administration.' : ''}`, 'info-circle', 9000);
                        }
                    } catch (releaseError) {
                        console.warn('Could not create the release request:', releaseError);
                        showNotification("Le formulaire est enregistré, mais la demande de divulgation n'a pas pu être transmise aux médecins : prévenez un administrateur.", 'warning', 9000);
                    }
                }
                // Exemption cochée sans être établie (ni drapeau, ni mineur) : la demande part avec le rapport, au nom du patient ou du soignant qui s'engage.
                if ((Number(bbCodeVersion) === 3 || Number(bbCodeVersion) === 25) && (formData.isExempt === true || formData.isExempt === 'true') && formData.exemptSource === 'demande') {
                    try {
                        const own = normalizePatientId(formData.patientID) === normalizePatientId(isCivilian ? civilianProfile?.patientID : myPatientID);
                        const outcome = await requestExemption({
                            patientID: formData.patientID,
                            patientName: formData.patientName || [formData.patientFirstName, formData.patientLastName].filter(Boolean).join(' '),
                            motif: formData.exemptMotif || 'faible_revenu',
                            byStaff: !isCivilian && !own && staffName ? { uid: currentEmployee?.uid, nom: staffName } : null,
                            patientEmail: formData.patientEmail || '',
                            requesterEmail: currentEmployee?.email || '',
                        });
                        if (outcome.status === 'demandee') showNotification('Demande d\'exemption transmise au personnel administratif.', 'info-circle', 6000);
                    } catch (exemptionError) {
                        console.warn('Could not request exemption:', exemptionError);
                    }
                }
            }

            // Rapport de décès (« Services de Médecine Légale ») avec un ID patient : le patient est déclaré décédé, le personnel
            // soignant ne peut plus rien enregistrer sur lui tant qu'un admin ne débloque pas la fiche (ou que ce rapport est supprimé).
            if (formData.patientID && locksPatient(bbCodeVersion) && writerIsDmec) {
                try {
                    const declared = await declareDeath({ patientID: formData.patientID, reportPath, authorName: currentAuthor, title: pureTitle });
                    if (declared) showNotification(`Patient ${normalizePatientId(formData.patientID)} déclaré décédé : le personnel soignant ne peut plus enregistrer sur son dossier.`, 'warning', 8000);
                } catch (lockError) {
                    console.warn('Could not declare the patient as deceased:', lockError);
                    showNotification("Le rapport est enregistré, mais le blocage du dossier du patient n'a pas pu être posé : prévenez un administrateur.", 'warning', 9000);
                }
            }

            // Journal d'activité (le contenu médical n'y figure pas : seulement le type de formulaire et l'auteur).
            logActivity({
                category: 'rapports',
                action: 'report_saved',
                summary: `Rapport enregistré : ${getFormDefinition(bbCodeVersion)?.name || `formulaire ${bbCodeVersion}`}`,
                details: `Auteur : ${currentAuthor}
Clé : ${sanitizedKey}`,
                target: currentAuthor,
                severity: 'success',
            });

            return { success: true }; // Indicate success

        } catch (error) {
            console.error("Error saving report to Firebase:", error);
            Sentry.captureException(error, { extra: { context: 'Firebase set report' } });
            const message = 'Something unexpected went wrong, report copied to clipboard!';
            showNotification(message, 'error');
            return { success: false, error: message }; // Indicate failure
        }
    };

    const handleCopyAndNotify = async () => {
        const bbCodeContent = getBBCodeContent();
        if (!bbCodeContent) {
            showNotification('BBCode content is empty, cannot copy.', 'error');
            return;
        }

        const saveReportResult = await saveReport();
        if (saveReportResult.success) {
            navigator.clipboard.writeText(String(bbCodeContent).replace(/\[img=\d+\]/gi, '[img]')).then(() => {
                showNotification('BBCode copied to clipboard and report saved!', 'success');
            }).catch(err => {
                showNotification('Report saved, but failed to copy BBCode to clipboard.', 'warning');
                console.error('Clipboard copy failed:', err);
            });
        } else {
            // Notification is shown by saveReport on failure
        }
    };

    const loadUserSavedReports = useCallback(async (userId) => {
        if (!userId) {
            setSavedReports([]);
            setSelectedUserForSavedReports(null);
            return;
        }

        setIsLoadingUserReports(true);
        setSelectedUserForSavedReports(userId);
        const loadingNotifId = showNotification(`Loading reports for ${userId}...`, 'info-circle', 0);

        const sanitizedUserId = comprehensiveSanitize(userId);
        const userReportsPath = `savedReports/${sanitizedUserId}`;
        const reportsRef = ref(database, userReportsPath);

        try {
            const snapshot = await get(reportsRef);
            removeNotification(loadingNotifId);

            if (snapshot.exists()) {
                const reportsData = snapshot.val();
                const validReports = [];

                // Un rapport « retiré » par son créateur (alors qu'une copie existe encore chez un
                // médecin) reste en base mais n'apparaît plus dans sa liste ni dans celle du patient.
                for (const reportKey in reportsData) {
                    const report = reportsData[reportKey];
                    if (report && report.ownerDeleted) continue;
                    validReports.push({
                        key: reportKey,
                        originalKey: report.originalKey,
                        title: report.title || null,
                        creatorName: report.creatorName || report.originalAuthorName || report.authorName,
                        isCopy: !!report.copiedFrom,
                        copiedFrom: report.copiedFrom || null,
                        publie: report.publie === true,
                        kind: report.kind || null,
                        imageUrl: report.imageUrl || report.data?.imageUrl || null,
                        bbCodeVersion: report.bbCodeVersion,
                        timestamp: report.timestamp,
                        authorName: report.authorName,
                        bbCode: report.bbCode,
                        // Utilisé par les boutons "Partager avec le patient" /
                        // "Récupérer une copie" (Lot 5).
                        patientID: report.data?.patientID || null,
                        reportPath: `${userReportsPath}/${reportKey}`,
                    });
                }

                validReports.sort((a, b) => b.timestamp - a.timestamp);
                setSavedReports(validReports);

                if (validReports.length > 0) {
                    showNotification(`Loaded ${validReports.length} report(s) for ${userId}.`, 'check-circle');
                } else {
                    showNotification(`No active reports found for ${userId}.`, 'info-circle');
                }

            } else {
                setSavedReports([]);
                showNotification(`No reports found for ${userId}.`, 'info-circle');
            }
        } catch (error) {
            removeNotification(loadingNotifId);
            console.error(`Error loading reports for user ${userId}:`, error);
            Sentry.captureException(error, { extra: { context: 'loadUserSavedReports', userId } });
            showNotification(`Failed to load reports for ${userId}.`, 'error');
            setSavedReports([]);
        } finally {
            setIsLoadingUserReports(false);
        }
    }, [showNotification, removeNotification, setSavedReports, setSelectedUserForSavedReports, setIsLoadingUserReports, database]);

    const loadReportForUser = useCallback(async (reportFirebaseKey, userId, returnOnly = false) => {
        if (!userId || !reportFirebaseKey) {
            if (!returnOnly) showNotification('Cannot load report: User ID or Report Key is missing.', 'error');
            return { success: false, message: 'User ID or Report Key is missing.' };
        }

        // Normalize coroner and phmc list data to arrays
        const coronersArray = Array.isArray(coronerListData)
        ? coronerListData
        : Object.values(coronerListData || {});

        const phmcArray = Array.isArray(phmcListData)
        ? phmcListData
        : Object.values(phmcListData || {});

        const sanitizedUserId = comprehensiveSanitize(userId);
        const reportPath = `savedReports/${sanitizedUserId}/${reportFirebaseKey}`;
        const reportRef = ref(database, reportPath);

        let loadingNotifId;
        if (!returnOnly) { // Only show notification if we are directly loading into the form
            loadingNotifId = showNotification(`Loading report: ${reportFirebaseKey} for ${userId}...`, 'info-circle', 0);
        }

            try {
                const snapshot = await get(reportRef);
                if (snapshot.exists()) {
                    const reportData = snapshot.val();
                    const loadedVersion = reportData.bbCodeVersion;
                    // Certains rapports (ex. formulaire AMA) n'ont pas de formulaire à remplir.
                    if (!returnOnly && !getFormDefinition(loadedVersion)?.FieldComponent) {
                        showNotification('Ce rapport ne peut pas être rechargé dans un formulaire (il n\'a pas de formulaire associé).', 'warning');
                        return { success: false, message: 'No form for this report.' };
                    }
                    let loadedBbCode = reportData.bbCode || '';
                    let loadedFormData = reportData.data || {};
                    // Anciens rapports « Email interne » : clés partagées renommées.
                    if (loadedVersion === 27) loadedFormData = migrateInternalEmailData(loadedFormData);

                    if (returnOnly) {
                        // When attaching, convert [bold] to [b]
                        const boldMatches = (loadedBbCode.match(/\[bold\]/gi) || []).length;
                        if (boldMatches > 0) {
                            console.log(`[useReportManagement] Found ${boldMatches} [bold] tags. Converting to [b].`);
                            loadedBbCode = loadedBbCode.replace(/\[bold\]/gi, '[b]').replace(/\[\/bold\]/gi, '[/b]');
                            console.log(`[useReportManagement] Conversion complete.`);
                        }
                    } else {
                        // When loading into the form, ensure any escaped bold tags are converted to simple [b]
                        loadedBbCode = loadedBbCode.replace(/\[bold\]/gi, '[b]').replace(/\[\/bold\]/gi, '[/b]');
                        // Dossier patient : reprendre un formulaire (Basique, Avancé, Mise à jour) le MODIFIE sur place tant que c'est permis (voir saveReport).
                        if (isDossierVersion(loadedVersion)) loadedFormData = { ...loadedFormData, dossierEditPath: reportPath };
                    }
                    const loadedCoronerEmployee = loadedFormData.coronerEmployee;
                    const loadedPhmcEmployee = loadedFormData.phmcEmployee;
                    const currentTimestamp = Date.now().toString();

                    if (loadedCoronerEmployee) {
                        const coronerDetails = coronersArray.find(c => c.name === loadedCoronerEmployee);
                        if (coronerDetails) {
                            loadedFormData.coronerEmployee = loadedCoronerEmployee;
                            loadedFormData.coronerBadge = coronerDetails.badge || '';
                            loadedFormData.coronerRank     = loadedFormData.coronerRank || inferCoronerRank(coronerDetails);
                            loadedFormData.coronerDiscord = coronerDetails.discord || '';
                            loadedFormData.coronerPHNumber = coronerDetails.phNumber || '50056';
                            if (!returnOnly) {
                                localStorage.setItem('coronerEmployee', loadedFormData.coronerEmployee);
                                localStorage.setItem('coronerEmployee_timestamp', currentTimestamp);
                                localStorage.setItem('coronerBadge', loadedFormData.coronerBadge);
                                localStorage.setItem('coronerBadge_timestamp', currentTimestamp);
                                localStorage.setItem('coronerRank', loadedFormData.coronerRank);
                                localStorage.setItem('coronerRank_timestamp', currentTimestamp);
                                localStorage.setItem('coronerDiscord', loadedFormData.coronerDiscord);
                                localStorage.setItem('coronerDiscord_timestamp', currentTimestamp);
                                localStorage.setItem('coronerPHNumber', loadedFormData.coronerPHNumber);
                                localStorage.setItem('coronerPHNumber_timestamp', currentTimestamp);
                            }
                        } else {
                            if (!returnOnly) showNotification(`Coroner "${loadedCoronerEmployee}" not found in current staff list. Using data from saved report.`, 'warning', 7000);
                            if (!returnOnly) {
                                if (loadedFormData.coronerEmployee) localStorage.setItem('coronerEmployee_timestamp', currentTimestamp);
                                if (loadedFormData.coronerBadge) localStorage.setItem('coronerBadge_timestamp', currentTimestamp);
                                if (loadedFormData.coronerRank) localStorage.setItem('coronerRank_timestamp', currentTimestamp);
                                if (loadedFormData.coronerDiscord) localStorage.setItem('coronerDiscord_timestamp', currentTimestamp);
                                if (loadedFormData.coronerPHNumber) localStorage.setItem('coronerPHNumber_timestamp', currentTimestamp);
                            }
                        }
                    } else if (!returnOnly) {
                        const coronerFieldsToClear = ['coronerEmployee', 'coronerBadge', 'coronerRank', 'coronerDiscord', 'coronerPHNumber'];
                        coronerFieldsToClear.forEach(field => {
                            localStorage.removeItem(field);
                            localStorage.removeItem(`${field}_timestamp`);
                        });
                    }

                    if (loadedPhmcEmployee) {
                        const phmcDetails = phmcArray.find(p => p.name === loadedPhmcEmployee);
                        if (phmcDetails) {
                            loadedFormData.phmcEmployee = loadedPhmcEmployee;
                            loadedFormData.phmcEmployeeLastName = phmcDetails.lastName || '';
                            loadedFormData.phmcRank = phmcDetails.category || phmcDetails.rank || '';
                            if (!returnOnly) {
                                localStorage.setItem('phmcEmployee', loadedFormData.phmcEmployee);
                                localStorage.setItem('phmcEmployee_timestamp', currentTimestamp);
                                localStorage.setItem('phmcEmployeeLastName', loadedFormData.phmcEmployeeLastName);
                                localStorage.setItem('phmcEmployeeLastName_timestamp', currentTimestamp);
                                localStorage.setItem('phmcRank', loadedFormData.phmcRank);
                                localStorage.setItem('phmcRank_timestamp', currentTimestamp);
                            }
                        } else {
                            if (!returnOnly) showNotification(`PHMC Staff "${loadedPhmcEmployee}" not found in current staff list. Using data from saved report.`, 'warning', 7000);
                            if (!returnOnly) {
                                if (loadedFormData.phmcEmployee) localStorage.setItem('phmcEmployee_timestamp', currentTimestamp);
                                if (loadedFormData.phmcEmployeeLastName) localStorage.setItem('phmcEmployeeLastName_timestamp', currentTimestamp);
                                if (loadedFormData.phmcRank) localStorage.setItem('phmcRank_timestamp', currentTimestamp);
                            }
                        }
                    } else if (!returnOnly) {
                        const phmcFieldsToClear = ['phmcEmployee', 'phmcEmployeeLastName', 'phmcRank'];
                        phmcFieldsToClear.forEach(field => {
                            localStorage.removeItem(field);
                            localStorage.removeItem(`${field}_timestamp`);
                        });
                    }

                    const localStorageManagedFields = [
                        'placeOfDeath', 'pronouncedTimeOfDeath', 'dateTime', 'department',
                        'mannerOfDeath',
                    ];
                    localStorageManagedFields.forEach(field => {
                        if (loadedFormData.hasOwnProperty(field) && loadedFormData[field]) {
                            if (!returnOnly) {
                                localStorage.setItem(field, loadedFormData[field]);
                                localStorage.setItem(`${field}_timestamp`, currentTimestamp);
                            }
                        }
                    });
                    // --- End Employee Sync Logic ---

                    if (!returnOnly) {
                        if (loadedVersion === 11) {
                            // Mass Fatality Report: set decedents array and other relevant fields
                            const decedents = Array.isArray(loadedFormData.decedents) ? loadedFormData.decedents.map(dec => ({
                                ...dec,
                                decedentName: dec.decedentName || dec.DecedentName,
                                decedentOOC: dec.decedentOOC || dec.DecedentOOC,
                            })) : [];

                            // On bascule d'abord sur le bon formulaire, PUIS on le remplit
                            // (voir l'effet pendingFormLoad plus bas).
                            setPendingFormLoad({
                                version: loadedVersion,
                                data: { ...loadedFormData, decedents },
                                label: reportData.originalKey || reportFirebaseKey,
                            });
                        } else if (bbCodeVersion === 2 && loadedVersion === 1) {
                            // ...existing code for v2 loading v1...
                            const currentDeathReportIsEmpty = !formData.deathReport || formData.deathReport.trim() === '';
                            let notificationMessage = '';
                            setFormData(prevFormData => {
                                let updatedName = prevFormData.decedentName || '';
                                let updatedOoc = prevFormData.decedentOOC || '';
                                let updatedDeathReport = prevFormData.deathReport || '';
                                let updatedAdditionalReports = prevFormData.additionalReports || [];
                                if (prevFormData.decedentName && loadedFormData.decedentName) {
                                    updatedName = `${prevFormData.decedentName}, ${loadedFormData.decedentName}`;
                                } else {
                                    updatedName = loadedFormData.decedentName || prevFormData.decedentName || '';
                                }
                                if (prevFormData.decedentOOC && loadedFormData.decedentOOC) {
                                    updatedOoc = `${prevFormData.decedentOOC}, ${loadedFormData.decedentOOC}`;
                                } else {
                                    updatedOoc = loadedFormData.decedentOOC || prevFormData.decedentOOC || '';
                                }
                                if (currentDeathReportIsEmpty) {
                                    updatedDeathReport = loadedBbCode;
                                    notificationMessage = `Loaded report for ${loadedFormData.decedentName || reportData.originalKey} into main Death Report field.`;
                                } else {
                                    updatedAdditionalReports = [...updatedAdditionalReports, loadedBbCode];
                                    notificationMessage = `Added report for ${loadedFormData.decedentName || reportData.originalKey} as an additional report.`;
                                }
                                const finalDataToSet = {
                                    ...prevFormData,
                                    ...loadedFormData,
                                    decedentName: updatedName,
                                    decedentOOC: updatedOoc,
                                    deathReport: updatedDeathReport,
                                    additionalReports: updatedAdditionalReports,
                                };
                                return finalDataToSet;
                            });
                            showNotification(notificationMessage, 'plus-circle');
                        } else {
                            // On bascule d'abord sur le bon formulaire, PUIS on le remplit
                            // (voir l'effet pendingFormLoad plus bas).
                            setPendingFormLoad({
                                version: loadedVersion,
                                data: loadedFormData,
                                label: reportData.originalKey || reportFirebaseKey,
                            });
                        }
                        setShowSavedReports(false);
                    }
                    // Always return the processed data, regardless of `returnOnly`
                    return { success: true, reportData: { ...reportData, data: loadedFormData, bbCode: loadedBbCode } };
                } else {
                    if (!returnOnly) showNotification(`Report not found in Firebase: ${reportFirebaseKey}`, 'error');
                    return { success: false, message: `Report not found in Firebase: ${reportFirebaseKey}` };
                }
            } catch (error) {
                console.error(`[loadReportForUser] Error loading report ${reportFirebaseKey} for user ${userId}:`, error);
                Sentry.captureException(error, { extra: { context: 'loadReportForUser', userId, reportFirebaseKey } });
                if (!returnOnly) showNotification(`Failed to load report: ${error.message}`, 'error');
                return { success: false, message: `Failed to load report: ${error.message}` };
            } finally {
                if (!returnOnly && loadingNotifId) {
                    removeNotification(loadingNotifId);
                }
            }
        }, [bbCodeVersion, coronerListData, phmcListData, removeNotification, setBbCodeVersion, setFormData, showNotification]);

    // « Charger » un rapport = ramener d'abord au BON formulaire, puis le remplir
    // (et non pas verser les champs dans le formulaire resté ouvert en fond, où
    // des champs d'un autre rapport traînaient et où les effets de montage du
    // formulaire pouvaient écraser les données chargées). On attend donc que le
    // bon formulaire soit affiché (et son code chargé, ils sont lazy-loaded)
    // avant d'y verser les données, en repartant d'un formulaire vierge.
    useEffect(() => {
        if (!pendingFormLoad) return undefined;
        if (bbCodeVersion !== pendingFormLoad.version) {
            formLoadRefs.current.setBbCodeVersion(pendingFormLoad.version);
            return undefined;
        }
        const timer = setTimeout(() => {
            const { initialFormData: blank, setFormData: applyFormData, showNotification: notify } = formLoadRefs.current;
            const loaded = pendingFormLoad.data || {};
            applyFormData((prev) => ({
                ...(blank || {}),
                ...loaded,
                // Identité du personnel : on garde celle déjà sélectionnée si le rapport n'en a pas.
                coronerEmployee: loaded.coronerEmployee || prev.coronerEmployee,
                coronerBadge: loaded.coronerBadge || prev.coronerBadge,
                coronerRank: loaded.coronerRank || prev.coronerRank,
                coronerDiscord: loaded.coronerDiscord || prev.coronerDiscord,
                phmcEmployee: loaded.phmcEmployee || prev.phmcEmployee,
            }));
            notify(`Rapport "${pendingFormLoad.label}" chargé dans son formulaire.`, 'upload');
            setPendingFormLoad(null);
        }, 500);
        return () => clearTimeout(timer);
    }, [pendingFormLoad, bbCodeVersion]);

    const handleReportSelectedForAttachment = useCallback(async (reportFirebaseKey, userId) => {
        // Le rappel est lu TOUT DE SUITE : la fenêtre se ferme (et réinitialise le rappel en attente)
        // pendant que le rapport se charge, ce qui provoquait « no callback » à la fin.
        const attachCallback = pendingReportAttachmentCallback.current;

        // When multiple reports are being loaded, we need to delay closing the modal.
        // This clears any pending close command from a previous, rapidly-fired event.
        if (modalCloseTimer.current) {
            clearTimeout(modalCloseTimer.current);
        }

        // Show a loading notification for this specific attachment
        const loadingNotifId = showNotification(`Attaching report...`, 'info-circle', 0);

        const result = await loadReportForUser(reportFirebaseKey, userId, true);

        // Remove the loading notification once done
        removeNotification(loadingNotifId);

        if (result.success && attachCallback) {
            const reportData = result.reportData;
            const loadedFormData = reportData.data || {};
            const loadedVersion = reportData.bbCodeVersion;

            // --- MODIFICATION START: Generalized Field Population ---
            setFormData(prev => {
                // Email DMEC : le formulaire vérifie le rapport joint, l'ajoute et reprend les noms du défunt (voir CoronerEmail.js).
                if (bbCodeVersion === 2) return prev;
                if (bbCodeVersion === 2 && loadedVersion === 11) { // Attaching Mass Fatality to Coroner Email
                    const decedents = loadedFormData.decedents;
                    if (decedents && decedents.length > 0) {
                        const firstDecedent = decedents[0];
                        let icName = firstDecedent.decedentName || firstDecedent.DecedentName || '';
                        let oocName = firstDecedent.decedentOOC || firstDecedent.DecedentOOC || '';

                        if (decedents.length > 1) {
                            icName += ` (x${decedents.length})`;
                            oocName += ` (x${decedents.length})`;
                        }
                        
                        const currentDeathReportIsEmpty = !prev.deathReport || prev.deathReport.trim() === '';
                        let newState = { ...prev };
                        newState.decedentName = icName;
                        newState.decedentOOC = oocName;
                        newState.paperworkType = 'Mass Fatality';

                        if (currentDeathReportIsEmpty) {
                            newState.deathReport = reportData.bbCode;
                        } else {
                            newState.additionalReports = [...(prev.additionalReports || []), reportData.bbCode];
                        }
                        return newState;
                    }
                    return prev;
                }
                // Mass Fatality Report (bbCodeVersion 11): attach BBCode to deathReport and merge decedents
                if (loadedVersion === 11) {
                    const currentDeathReportIsEmpty = !prev.deathReport || prev.deathReport.trim() === '';
                    let newState = { ...prev };
                    if (currentDeathReportIsEmpty) {
                        newState.deathReport = reportData.bbCode;
                    } else {
                        newState.additionalReports = [...(prev.additionalReports || []), reportData.bbCode];
                    }
                    // Merge decedents array if present
                    if (Array.isArray(loadedFormData.decedents)) {
                        newState.decedents = [...(prev.decedents || []), ...loadedFormData.decedents];
                    }
                    return newState;
                }
                // ...existing code...
                const fieldsToUpdate = {
                    decedentName: loadedFormData.decedentName,
                    decedentOOC: loadedFormData.decedentOOC,
                    requestingOfficer: loadedFormData.requestingOfficer,
                    department: loadedFormData.department,
                };
                if (bbCodeVersion === 2) {
                    // If there's already a name, append the new one.
                    let newState = { ...prev };
                    newState.decedentName = prev.decedentName && fieldsToUpdate.decedentName ? `${prev.decedentName}, ${fieldsToUpdate.decedentName}` : fieldsToUpdate.decedentName || prev.decedentName || '';
                    newState.decedentOOC = prev.decedentOOC && fieldsToUpdate.decedentOOC ? `${prev.decedentOOC}, ${fieldsToUpdate.decedentOOC}` : fieldsToUpdate.decedentOOC || prev.decedentOOC || '';
                    newState.requestingOfficer = fieldsToUpdate.requestingOfficer || prev.requestingOfficer;
                    newState.department = fieldsToUpdate.department || prev.department;
                    if (loadedVersion === 1 && bbCodeVersion === 2) {
                        const currentDeathReportIsEmpty = !prev.deathReport || prev.deathReport.trim() === '';
                        if (currentDeathReportIsEmpty) {
                            newState.deathReport = reportData.bbCode;
                        } else {
                            newState.additionalReports = [...(prev.additionalReports || []), reportData.bbCode];
                        }
                    }
                    return newState;
                } else {
                    let newState = { ...prev };
                    newState.decedentName = fieldsToUpdate.decedentName || prev.decedentName;
                    newState.decedentOOC = fieldsToUpdate.decedentOOC || prev.decedentOOC;
                    newState.requestingOfficer = fieldsToUpdate.requestingOfficer || prev.requestingOfficer;
                    newState.department = fieldsToUpdate.department || prev.department;
                    return newState;
                }
            });
            // --- MODIFICATION END ---

            // The pending callback now primarily handles form-specific fields like 'attachedReportSummary'
            const attachOutcome = attachCallback(reportData);

            // Un rapport refusé par le formulaire (ex. certificat : rapport non accepté) retourne false.
            if (attachOutcome !== false) {
                showNotification(`Report "${reportData.originalKey}" attached successfully.`, 'check-circle');
            }

        } else {
            if (!result.success) {
                showNotification('Échec du chargement du rapport sélectionné.', 'error');
            } else if (!attachCallback) {
                showNotification('Le processus de pièce jointe n’a pas pu être terminé (no callback).', 'error');
                Sentry.captureMessage('handleReportSelectedForAttachment was called but pendingReportAttachmentCallback.current was null.');
            }
        }

        // Set a timer to close the modal. If another report is loaded quickly,
        // the timer will be reset, ensuring the modal only closes after the last report is processed.
        modalCloseTimer.current = setTimeout(() => {
            setReportSelectionFilter(null);
            setPreselectedEmployeeType(null);
            setShowSavedReports(false);
        }, 1000); // 1-second delay

    }, [bbCodeVersion, loadReportForUser, modalCloseTimer, removeNotification, setFormData, showNotification]);

    const onAttachReportSummaryRequest = useCallback((callback) => {
        // Même logique que toggleSavedReports : plus de gate sur le formulaire,
        // SavedReportsModal gère l'accès selon la connexion (voir plus haut).
        pendingReportAttachmentCallback.current = callback;
        // Rapports acceptés pour un certificat médical (voir utils/employerSummary.js).
        setReportSelectionFilter(ACCEPTED_REPORT_VERSIONS);
        setPreselectedEmployeeType('PHMC'); // Set to PHMC for this specific use case
        setShowSavedReports(true);
    }, [ER_PROTOCOL_VERSION, CONSULTATION_NOTES_PBC_VERSION, CONSULTATION_NOTES_PHMC_VERSION, setReportSelectionFilter, setPreselectedEmployeeType, setShowSavedReports]);

    // --- Regroupement des dossiers par patient (Lot 5) ---

    // Complète savedReports (déjà chargé pour l'auteur courant) avec les
    // rapports d'un patient explicitement PARTAGÉS par le personnel — ces
    // rapports vivent sous le savedReports d'un AUTRE auteur, donc invisibles
    // via le chargement author-scoped habituel. Utilisé par la vue Civil
    // ("Dossiers/Candidatures sauvegardées") : ses propres rapports viennent
    // déjà de loadUserSavedReports, ceci n'ajoute que ce qui lui a été partagé.
    const loadSharedReportsForPatient = useCallback(async (patientID) => {
        if (!patientID) return;
        try {
            // Retrouve l'index quelle que soit la façon dont l'ID a été saisi (PHMC-1234,
            // phmc-1234, 1234…), puis ne garde que ce que le personnel a PARTAGÉ.
            const dossier = await loadPatientDossier(patientID);
            const validShared = dossier
                .filter((e) => e.visibility === 'shared' && !e.ownerDeleted)
                .map((e) => ({
                    key: e.indexKey,
                    originalKey: e.originalKey,
                    title: e.title,
                    creatorName: e.creatorName,
                    kind: e.kind,
                    imageUrl: e.imageUrl,
                    bbCodeVersion: e.bbCodeVersion,
                    timestamp: e.timestamp,
                    authorName: e.authorName,
                    bbCode: e.bbCode,
                    patientID: e.patientID || patientID,
                    patientNode: e.patientNode,
                    reportPath: e.reportPath,
                    sharedByStaff: true,
                }));
            if (validShared.length > 0) {
                setSavedReports((prev) => {
                    const existingKeys = new Set(prev.map((r) => r.key));
                    return [...prev, ...validShared.filter((r) => !existingKeys.has(r.key))];
                });
            }
        } catch (error) {
            console.error('Error loading shared patient reports:', error);
            Sentry.captureException(error, { extra: { context: 'loadSharedReportsForPatient', patientID } });
        }
    }, []);

    // Dossier d'un CIVIL chargé via son index patientRecords (par ID patient), et NON par savedReports/{nom}
    // (nœud dont les règles ne peuvent pas vérifier qu'il appartient au compte). Résilient à la suppression/
    // recréation de compte : l'ID patient est stable. Le civil voit SES rapports (owner) et ceux que le
    // personnel lui a partagés (shared) ; jamais les "staff-only" non partagés. REMPLACE la liste affichée.
    const loadCivilianDossier = useCallback(async (patientID) => {
        if (!patientID) { setSavedReports([]); return; }
        setIsLoadingUserReports(true);
        setSelectedUserForSavedReports(null);
        try {
            const dossier = await loadPatientDossier(patientID);
            const entries = dossier
                .filter((e) => (e.visibility === 'owner' || e.visibility === 'shared') && !e.ownerDeleted)
                .map((e) => ({
                    key: e.indexKey,
                    originalKey: e.originalKey,
                    title: e.title,
                    creatorName: e.creatorName,
                    isCopy: !!e.copiedFrom,
                    copiedFrom: e.copiedFrom || null,
                    kind: e.kind,
                    imageUrl: e.imageUrl,
                    bbCodeVersion: e.bbCodeVersion,
                    timestamp: e.timestamp,
                    authorName: e.authorName,
                    bbCode: e.bbCode,
                    patientID: e.patientID || patientID,
                    patientNode: e.patientNode,
                    reportPath: e.reportPath,
                    sharedByStaff: e.visibility === 'shared',
                }));
            entries.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
            setSavedReports(entries);
        } catch (error) {
            console.error('Error loading civilian dossier:', error);
            Sentry.captureException(error, { extra: { context: 'loadCivilianDossier', patientID } });
            setSavedReports([]);
        } finally {
            setIsLoadingUserReports(false);
        }
    }, []);

    // Action personnel : rend un rapport visible au patient concerné dans sa
    // propre vue "Dossiers/Candidatures sauvegardées" (patientRecords passe de
    // staff-only à shared — le rapport lui-même n'est ni déplacé ni dupliqué).
    // patientNode : nœud d'index où vit réellement l'entrée (voir loadPatientDossier) ;
    // sinon on cherche parmi tous les nœuds qui désignent ce patient (« 2704 »,
    // « PHMC-2704 », ancien nœud mal formé…).
    const findIndexLocation = async (patientID, indexKey, patientNode) => {
        const nodes = patientNode ? [patientNode] : await findPatientNodes(patientID);
        for (const node of nodes) {
            const snap = await get(ref(database, `patientRecords/${node}/${indexKey}`));
            if (snap.exists()) return { node, entry: snap.val() };
        }
        return null;
    };

    const shareReportWithPatient = useCallback(async (patientID, reportKey, patientNode) => {
        if (isLockdownOn()) { showNotification(LOCK_MESSAGE, 'warning'); return; }
        if (!patientID || !reportKey) return;
        try {
            const location = await findIndexLocation(patientID, reportKey, patientNode);
            if (!location) {
                showNotification("Ce rapport n'est pas encore indexé dans le dossier du patient (ré-indexation admin nécessaire).", 'warning');
                return;
            }
            const { entry } = location;
            // Une COPIE ne se repartage pas : seul le créateur du rapport d'origine décide
            // de le montrer au patient (sinon on pourrait partager 30 fois le même rapport).
            if (entry.copiedFrom) {
                showNotification("Ce rapport est une copie : seul le créateur du rapport d'origine peut le partager avec le patient.", 'warning');
                return;
            }
            if (entry.visibility === 'shared') {
                showNotification('Ce rapport est déjà partagé avec le patient.', 'info-circle');
                return;
            }
            if (entry.visibility === 'owner') {
                showNotification('Ce rapport a été créé par le patient lui-même : il le voit déjà.', 'info-circle');
                return;
            }
            // Chacun partage SES rapports ; un administrateur ou un chef de service peut partager tous ceux du dossier.
            if (!canShareReport({ authorName: entry.creatorName || entry.authorName, staffName, isAdmin, isChief: isServiceChief(staffProfile) })) {
                showNotification("Seul le médecin qui a créé ce rapport, un chef de service ou un administrateur peut le partager avec le patient.", 'warning');
                return;
            }
            await set(ref(database, `patientRecords/${location.node}/${reportKey}/visibility`), 'shared');
            logActivity({
                category: 'rapports', action: 'report_shared', summary: `Rapport partagé avec le patient : ${entry.title || entry.originalKey || reportKey}`,
                details: `Patient : ${location.node}\nPartagé par : ${staffName || 'admin'}`, target: location.node,
            });
            showNotification('Rapport partagé avec le patient.', 'check-circle');
            findCivilianUidByPatientId(location.node).then((uid) => notifyUser(uid, { type: 'partage', titre: 'Un rapport a été partagé avec vous', texte: entry.title || entry.originalKey || undefined, lien: { cible: 'dossierPatient' } }));
        } catch (error) {
            console.error('Error sharing report with patient:', error);
            Sentry.captureException(error, { extra: { context: 'shareReportWithPatient', patientID, reportKey } });
            showNotification('Erreur lors du partage du rapport.', 'error');
        }
    }, [showNotification, staffName, isAdmin, staffProfile]);

    // Action personnel : duplique un rapport (créé par un civil, ou par un collègue) dans
    // son PROPRE savedReports, pour le consulter plus tard indépendamment de l'auteur
    // d'origine. Le rapport d'origine n'est ni modifié ni supprimé ; il garde un marqueur
    // « copié par ». Règles : UNE seule copie par médecin et par rapport ; on copie
    // toujours le rapport d'origine (jamais la copie d'un collègue) ; pas de copie de ses
    // propres rapports. copyAuthorName DOIT être le nom du médecin (jamais son e-mail) :
    // c'est la clé sous laquelle sa liste « Rapports enregistrés » est chargée.
    const copyReportToOwnAccount = useCallback(async (reportPath, copyAuthorName, meta = {}) => {
        if (isLockdownOn()) { showNotification(LOCK_MESSAGE, 'warning'); return; }
        if (!reportPath || !copyAuthorName) {
            showNotification('Impossible de déterminer votre identité pour la copie.', 'error');
            return;
        }
        try {
            const sanitizedCopyAuthorId = sanitizeAuthorKey(copyAuthorName);
            let sourcePath = reportPath;
            let snap = await get(ref(database, sourcePath));
            if (!snap.exists()) {
                showNotification('Rapport introuvable.', 'error');
                return;
            }
            let original = snap.val();

            // Une copie de copie n'a pas de sens : on remonte au rapport d'origine.
            if (original.copiedFrom?.reportPath) {
                sourcePath = original.copiedFrom.reportPath;
                snap = await get(ref(database, sourcePath));
                if (!snap.exists()) {
                    showNotification("Le rapport d'origine de cette copie n'existe plus.", 'error');
                    return;
                }
                original = snap.val();
            }

            if (sourcePath.split('/')[1] === sanitizedCopyAuthorId) {
                showNotification("Ce rapport est déjà dans vos rapports enregistrés : inutile d'en faire une copie.", 'info-circle');
                return;
            }

            const originalKeyInPath = sourcePath.split('/').pop();
            const patientID = original.data?.patientID || meta.patientID || null;
            const location = patientID ? await findIndexLocation(patientID, originalKeyInPath, null) : null;

            // UNE copie par médecin : marqueur sur l'original, et vérification dans le dossier
            // (au cas où le marqueur manquerait sur un ancien rapport).
            let alreadyCopied = !!location?.entry?.copiedBy?.[sanitizedCopyAuthorId];
            if (!alreadyCopied && patientID) {
                const dossierNodes = await findPatientNodes(patientID);
                for (const node of dossierNodes) {
                    const nodeSnap = await get(ref(database, `patientRecords/${node}`));
                    const nodeEntries = nodeSnap.exists() ? Object.values(nodeSnap.val() || {}) : [];
                    if (nodeEntries.some((e) => e && e.copiedFrom?.reportPath === sourcePath
                        && sanitizeAuthorKey(e.authorName) === sanitizedCopyAuthorId)) {
                        alreadyCopied = true;
                        break;
                    }
                }
            }
            if (alreadyCopied) {
                showNotification('Vous avez déjà une copie de ce rapport dans vos rapports enregistrés (une seule copie par médecin).', 'info-circle');
                return;
            }

            if (patientID && !isAdmin && !readFamiliesOf(staffProfile).dmec && await loadDeathLock(patientID)) {
                showNotification(DEATH_LOCK_MESSAGE, 'warning', 10000);
                return;
            }

            const copyKey = sanitizeAuthorKey(original.originalKey || originalKeyInPath) + '_copie_' + Date.now();
            const copyPath = `savedReports/${sanitizedCopyAuthorId}/${copyKey}`;
            const creator = original.creatorName || original.originalAuthorName || original.authorName || '';
            const copyPayload = sanitizeForFirebase({
                ...original,
                ownerDeleted: null,
                publie: null, publieLe: null, publiePar: null, depublication: null,
                authorName: copyAuthorName,
                creatorName: creator,
                timestamp: Date.now(),
                title: reportTitleOf(original),
                copiedFrom: { reportPath: sourcePath, patientNode: location?.node || null, indexKey: originalKeyInPath },
            });
            await set(ref(database, copyPath), copyPayload);

            if (patientID) {
                const node = location?.node || normalizePatientId(patientID);
                await writeIndexEntry({
                    patientID: node,
                    indexKey: copyKey,
                    entry: {
                        reportPath: copyPath,
                        // Une copie reste privée : elle ne peut jamais être partagée au patient.
                        visibility: 'staff-only',
                        bbCodeVersion: original.bbCodeVersion,
                        originalKey: original.originalKey,
                        title: reportTitleOf(original),
                        kind: original.kind || null,
                        authorName: copyAuthorName,
                        creatorName: creator,
                        patientName: original.data?.patientName || location?.entry?.patientName || null,
                        timestamp: Date.now(),
                        copiedFrom: { reportPath: sourcePath, patientNode: node, indexKey: originalKeyInPath },
                    },
                });
                // Marqueur sur l'original (best-effort : n'empêche pas la copie).
                if (location) {
                    try {
                        await set(ref(database, `patientRecords/${node}/${originalKeyInPath}/copiedBy/${sanitizedCopyAuthorId}`), copyKey);
                    } catch (markerError) {
                        console.warn('Could not mark original as copied:', markerError);
                    }
                }
            }

            showNotification(`Copie enregistrée dans les rapports de ${copyAuthorName}.`, 'save');
            // Prévient l'auteur du rapport copié (membre du personnel, sinon le patient lui-même).
            (async () => {
                const uid = (await findStaffUidByNode(sourcePath.split('/')[1], sanitizeAuthorKey)) || (patientID ? await findCivilianUidByPatientId(patientID) : null);
                notifyUser(uid, { type: 'copie', titre: `${copyAuthorName} a copié l'un de vos rapports`, texte: reportTitleOf(original) || undefined, lien: { cible: 'rapports' } });
            })();
            logActivity({
                category: 'rapports', action: 'report_copied', summary: `Rapport copié vers les rapports de ${copyAuthorName}`,
                details: `Chemin source : ${sourcePath}
Copie : ${copyPath}`, target: copyAuthorName,
            });

            // La liste affichée est déjà chargée : sans rechargement, la copie
            // n'apparaît pas avant la prochaine ouverture de la modale.
            if (selectedUserForSavedReports && sanitizeAuthorKey(selectedUserForSavedReports) === sanitizedCopyAuthorId) {
                loadUserSavedReports(selectedUserForSavedReports);
            }
            return { success: true, copyKey, copyPath };
        } catch (error) {
            console.error('Error copying report:', error);
            Sentry.captureException(error, { extra: { context: 'copyReportToOwnAccount', reportPath } });
            showNotification('Erreur lors de la copie du rapport.', 'error');
        }
    }, [showNotification, selectedUserForSavedReports, loadUserSavedReports, isAdmin, staffProfile]);

    // Suppression d'un ou plusieurs rapports AVEC les règles du dossier patient
    // (voir deleteReportWithRules) : un médecin supprime ses rapports, un patient
    // supprime les siens (masqués s'il en existe une copie médecin) mais jamais
    // ceux créés par le personnel. Chaque rapport : { key, reportPath?, patientID?,
    // sharedByStaff?, patientNode? }.
    const deleteReportsForUser = useCallback(async (reports, userId, options = {}) => {
        const list = (Array.isArray(reports) ? reports : [reports]).filter(Boolean);
        const result = { deleted: 0, hidden: 0, refused: 0 };
        if (list.length === 0) return result;
        if (isLockdownOn()) { showNotification(LOCK_MESSAGE, 'warning'); return result; }
        const viewer = { role: isCivilian ? 'civil' : 'staff', isAdmin, staffName, myPatientID };
        const refusals = new Set();

        for (const report of list) {
            const reportPath = report.reportPath || `savedReports/${sanitizeAuthorKey(userId)}/${report.key}`;
            try {
                const outcome = await deleteReportWithRules({ ...report, reportPath }, viewer);
                if (outcome.action === 'deleted') result.deleted++;
                else if (outcome.action === 'hidden') result.hidden++;
                else { result.refused++; refusals.add(outcome.message); }
                // Toute suppression laisse une trace dans le journal ; celle d'un AMA (refus de soins signé par un patient) est signalée par un avertissement.
                if (outcome.action === 'deleted' || outcome.action === 'hidden') {
                    const isAma = report.kind === 'ama';
                    const label = report.title || report.key;
                    logActivity({
                        category: 'rapports', action: isAma ? 'ama_deleted' : 'report_deleted', severity: isAma ? 'warning' : 'info',
                        summary: `${isAma ? '⚠ Formulaire AMA ' : 'Rapport '}${report.isCopy ? '(copie) ' : ''}${outcome.action === 'hidden' ? 'retiré' : 'supprimé'} : ${label}`,
                        details: `${report.patientID ? `Patient : ${report.patientID}\n` : ''}Supprimé par : ${staffName || (isCivilian ? 'le patient' : 'compte sans fiche')}\nRapport : ${reportPath}\nRésultat : ${outcome.action === 'hidden' ? 'retiré (conservé dans le dossier tant que des copies existent)' : 'supprimé définitivement'}`,
                        target: report.patientID || userId || undefined,
                    });
                } else if (outcome.action === 'refused' && report.kind === 'ama') {
                    logActivity({
                        category: 'rapports', action: 'ama_delete_refused', severity: 'warning',
                        summary: `Tentative de suppression d'un AMA refusée : ${report.title || report.key}`,
                        details: `Patient : ${report.patientID || 'inconnu'}\nPar : ${staffName || (isCivilian ? 'le patient' : 'compte sans fiche')}`,
                        target: report.patientID || undefined,
                    });
                }
            } catch (error) {
                console.error(`Error deleting report ${report.key} for user ${userId}:`, error);
                Sentry.captureException(error, { extra: { context: 'deleteReportsForUser', userId, key: report.key } });
                result.refused++;
                refusals.add(`Impossible de supprimer un rapport : ${error.message}`);
            }
        }

        const done = result.deleted + result.hidden;
        if (done > 0) {
            const hiddenNote = result.hidden ? ` (dont ${result.hidden} conservé(s) dans le dossier tant que des copies existent)` : '';
            showNotification(`${done} rapport(s) supprimé(s)${hiddenNote}.`, 'trash');
        }
        refusals.forEach((message) => showNotification(message, 'warning', 7000));

        // Recharge la liste affichée (et, pour un civil, les rapports partagés).
        if (userId && !options.skipReload) {
            if (isCivilian && civilianProfile?.patientID) {
                await loadCivilianDossier(civilianProfile.patientID);
            } else {
                await loadUserSavedReports(userId);
            }
        }
        return result;
    }, [isCivilian, isAdmin, staffName, civilianProfile, loadUserSavedReports, loadCivilianDossier, showNotification]);

    // --- Pipeline de candidatures (Lot 6) ---

    // Une candidature par (civil, poste) : applicationId dérivé du bbCodeVersion
    // pour que "Enregistrer" mette à jour la même entrée au lieu d'en créer une
    // nouvelle à chaque clic. submitAction : 'save' (brouillon) | 'submit'
    // (candidater — envoie accusé de réception + notification Discord admin).
    const saveJobApplication = useCallback(async (submitAction) => {
        if (!applicant) {
            showNotification(staffProfile
                ? 'Les employés doivent d\'abord obtenir le statut de recrutement interne : utilisez « Demander le statut de recrutement interne ».'
                : 'Vous devez être connecté en tant que Civil pour gérer une candidature.', 'error');
            return { success: false };
        }
        const definition = getFormDefinition(bbCodeVersion);
        if (!definition || definition.group !== 'PHMC Recruitment') {
            showNotification('Ce formulaire n\'est pas une candidature.', 'error');
            return { success: false };
        }

        const bbCodeContent = getBBCodeContent();
        const applicantName = formData.applicantTitleAndFullName
            || `${applicant.firstName || ''} ${applicant.lastName || ''}`.trim();
        // Mode modification : l'enregistrement vise la candidature chargée (même identifiant), jamais une autre.
        const editing = editingApplication && Number(editingApplication.version) === Number(bbCodeVersion) ? editingApplication : null;
        let newStatus = submitAction === 'submit' ? 'soumise' : 'brouillon';

        try {
            let editedExisting = null;
            if (editing) {
                // Relecture juste avant d'écrire : un entretien a pu être programmé pendant que le formulaire était ouvert.
                editedExisting = await loadApplication(applicant.uid, editing.id);
                if (!editedExisting) {
                    showNotification('Cette candidature n\'existe plus : modification abandonnée.', 'error');
                    forgetEditing();
                    return { success: false };
                }
                if (!APPLICATION_EDITABLE_STATUSES.includes(editedExisting.statut)) {
                    showNotification("Un entretien a été programmé ou une décision rendue pendant votre modification : la candidature n'est plus modifiable. Vos changements n'ont pas été enregistrés.", 'warning', 10000);
                    forgetEditing();
                    return { success: false };
                }
                if (submitAction !== 'submit') newStatus = editedExisting.statut;
            }

            // Candidature existante (nouveau nœud « candidatures » ou ancien « jobApplications »).
            // Candidature déjà prise en charge (examen, entretien) : le formulaire ne peut plus la modifier ni la renvoyer.
            // Elle repasserait sinon à « brouillon » / « soumise » et ferait perdre sa place au candidat.
            const sameFormEarly = (await loadApplicationsOf(applicant.uid)).filter((a) => Number(a.versionBBCode) === Number(bbCodeVersion));
            const inProgress = editing ? null : sameFormEarly.find((a) => ['en_examen', 'entretien_programme', 'entretien_effectue'].includes(a.statut));
            if (inProgress) {
                showNotification(
                    inProgress.statut === 'en_examen'
                        ? `Votre candidature pour « ${inProgress.poste || 'ce poste'} » est en cours d'examen : utilisez « Modifier » dans « Mon dossier candidat » pour la changer, ou retirez-la pour en déposer une autre dans cette catégorie.`
                        : `Votre candidature pour « ${inProgress.poste || 'ce poste'} » est en cours de traitement par le recrutement (entretien) : elle ne peut plus être modifiée. Écrivez au recrutement depuis « Mon dossier candidat », ou retirez-la pour en déposer une autre dans cette catégorie.`,
                    'warning', 10000
                );
                return { success: false };
            }

            // Une candidature par domaine tant qu'elle est en cours (brouillon, envoyée, en pause, retirée…) : « Enregistrer »
            // met à jour la même. Une décision de l'administration (acceptée/refusée) est définitive et reste dans le dossier :
            // une nouvelle candidature dans ce domaine est alors une nouvelle entrée. Le premier identifiant « form_{version} »
            // est conservé tel quel pour ne pas dupliquer les candidatures déjà déposées.
            const sameForm = (await loadApplicationsOf(applicant.uid)).filter((a) => Number(a.versionBBCode) === Number(bbCodeVersion));
            const existing = editedExisting || sameForm
                .filter((a) => !['acceptee', 'refusee'].includes(a.statut))
                .sort((a, b) => (b.modifieLe || 0) - (a.modifieLe || 0))[0] || null;
            const applicationId = existing?.id || (sameForm.length > 0 ? `form_${bbCodeVersion}_${Date.now()}` : `form_${bbCodeVersion}`);

            // Plafond de candidatures actives (3 pour un Civil, 2 pour le personnel interne) : un NOUVEAU dépôt, ou la reprise d'une candidature en pause,
            // en ajoute une. Modifier une candidature déjà active n'en change pas le nombre.
            if (!existing || normalizeApplicationStatus(existing.statut) === 'en_pause') {
                const activeCount = countActiveApplications(await loadApplicationsOf(applicant.uid));
                if (activeCount >= maxActiveApplications(applicant.internal)) {
                    showNotification(applicationLimitMessage(activeCount, applicant.internal), 'warning', 10000);
                    return { success: false };
                }
            }

            // Conditions d'enregistrement : un brouillon exige au moins un poste ; l'envoi exige une candidature
            // complète pour un poste ouvert (voir utils/formValidation.js).
            const alreadySubmitted = !!editing && !['brouillon', 'en_pause'].includes(editedExisting.statut);
            const samePoste = !!editing && formData.recruitmentPosition === editedExisting.posteCle;
            const applicationCheck = validateApplication(bbCodeVersion, formData, {
                mode: submitAction === 'submit' || alreadySubmitted ? 'submit' : 'draft',
                existing: editing ? null : existing,
                selectOptions: samePoste ? null : selectOptions,   // poste fermé depuis l'envoi : sans effet si on ne le change pas
            });
            if (applicationCheck.errors.length > 0) {
                showNotification(
                    formatIssues(applicationCheck.errors, { title: submitAction === 'submit' ? 'Candidature incomplète :' : 'Brouillon impossible :' }),
                    'exclamation-circle', 10000
                );
                return { success: false };
            }

            // « Enregistrer » depuis le formulaire REMPLACE la candidature déjà enregistrée dans cette catégorie (un seul poste à la fois) :
            // on prévient, on demande une vraie confirmation, et on oriente vers « Modifier ma candidature » pour une simple retouche.
            const replacedPoste = !editing && existing?.posteCle && formData.recruitmentPosition && existing.posteCle !== formData.recruitmentPosition
                ? (existing.poste || existing.posteCle) : null;
            if (!editing && existing) {
                const newPosteLabel = positionLabelFor(selectOptions, bbCodeVersion, formData.recruitmentPosition) || formData.recruitmentPosition || '—';
                const message = [
                    `⚠ Vous avez déjà une candidature enregistrée dans cette catégorie : « ${existing.poste || existing.posteCle || 'poste inconnu'} ».`,
                    '',
                    '« Enregistrer » va la REMPLACER ENTIÈREMENT par ce formulaire : tout ce qui était enregistré avant (poste, réponses, texte) sera écrasé et ne pourra pas être récupéré.',
                    replacedPoste ? `Le poste changerait aussi : « ${replacedPoste} » → « ${newPosteLabel} ».` : '',
                    '',
                    'Si vous voulez seulement MODIFIER votre candidature, annulez ici et passez par « Mon dossier candidat » → « Modifier ma candidature » : elle sera mise à jour (sans rien écraser) et le recrutement verra précisément ce qui a changé.',
                    '',
                    'Confirmez-vous vouloir tout écraser ?',
                ].filter((line, index, list) => line !== '' || list[index - 1] !== '').join('\n');
                if (!window.confirm(message)) return { success: false };
            }

            const newDonnees = filterFormData(formData, bbCodeVersion);
            const newPoste = positionLabelFor(selectOptions, bbCodeVersion, formData.recruitmentPosition) || definition.name;
            // Ce que le candidat a changé (consigné dans l'historique pour le recrutement).
            let editEvent = null;
            if (editing) {
                const changedFields = changedApplicationFields(editedExisting.donnees, newDonnees);
                const posteChanged = (editedExisting.posteCle || '') !== (formData.recruitmentPosition || '');
                if (changedFields.length === 0 && !posteChanged && submitAction !== 'submit') {
                    showNotification('Aucune modification à enregistrer.', 'info-circle');
                    return { success: false };
                }
                const parts = [];
                if (posteChanged) parts.push(`Poste : ${editedExisting.poste || editedExisting.posteCle || '—'} → ${newPoste}`);
                if (changedFields.length > 0) parts.push(`Champs modifiés : ${changedFields.join(', ')}`);
                editEvent = { evenement: 'candidature_modifiee', details: parts.join(' ; ') || null, par: applicantName };
            }

            const historique = existing?.historique ? [...existing.historique] : [];
            historique.push({ statut: newStatus, horodatage: Date.now(), ...(editEvent || {}) });

            const payload = sanitizeForFirebase({
                candidatUid: applicant.uid,
                interne: applicant.internal || undefined,
                idPatient: applicant.patientID,
                nomCandidat: applicantName,
                // Libellé français du poste (la clé, souvent anglaise, est gardée à part).
                poste: newPoste,
                posteCle: formData.recruitmentPosition || null,
                versionBBCode: bbCodeVersion,
                donnees: newDonnees,
                bbcode: bbCodeContent,
                statut: newStatus,
                dateEntretien: existing?.dateEntretien || null,
                // Ce que le recrutement a renseigné ne doit pas disparaître quand le candidat enregistre.
                entretien: existing?.entretien || undefined,
                priseEnChargePar: existing?.priseEnChargePar || undefined,
                refus: existing?.refus || undefined,
                creeLe: existing?.creeLe || Date.now(),
                modifieLe: Date.now(),
                historique,
            });

            await saveApplication(applicant.uid, applicationId, payload);
            if (newStatus === 'soumise') notifyGroup('recrutement', { type: 'recrutement', titre: `Nouvelle candidature : ${payload.poste || definition.name}`, texte: applicantName, lien: { cible: 'recrutement' } });
            logActivity({
                category: 'recrutement',
                action: editing && submitAction !== 'submit' ? 'application_edited' : (submitAction === 'submit' ? 'application_submitted' : 'application_draft_saved'),
                summary: `${editing && submitAction !== 'submit' ? 'Candidature modifiée' : (submitAction === 'submit' ? 'Candidature envoyée' : 'Brouillon de candidature enregistré')} : ${applicantName} — ${payload.poste}`,
                details: `Formulaire : ${definition.name}
Candidature : ${applicationId}`,
                target: applicantName,
                severity: submitAction === 'submit' ? 'success' : 'info',
            });

            if (submitAction === 'submit') {
                // Best-effort : un mail/webhook raté ne doit jamais faire échouer
                // la candidature elle-même (déjà persistée à ce stade).
                if (applicant.email) {
                    sendTemplatedMail('candidature_recue', { to: applicant.email, vars: { nom: applicantName, poste: payload.poste || definition.name } });
                }

                const discordWebhookUrl = null || null;
                if (discordWebhookUrl) {
                    sendPhmcRecruitmentWebhook({
                        webhookUrl: discordWebhookUrl,
                        formData,
                        commitInfo: {},
                        actionMessage: 'Nouvelle candidature soumise (compte Civil)',
                        selectOptions,
                        formDefinition: definition,
                    }).catch((err) => console.warn('Webhook Discord candidature échoué:', err));
                }
            }

            showNotification(
                editing && submitAction !== 'submit'
                    ? 'Modifications enregistrées : le recrutement verra ce qui a changé dans l\'historique.'
                    : `${submitAction === 'submit' ? 'Candidature envoyée !' : 'Candidature enregistrée (brouillon).'}${replacedPoste ? ` Elle remplace votre candidature pour « ${replacedPoste} ».` : ''}`,
                'save'
            );
            if (editing) forgetEditing();
            return { success: true };
        } catch (error) {
            console.error('Error saving job application:', error);
            if (error?.code === 'lockdown') { showNotification(LOCK_MESSAGE, 'warning'); return { success: false }; }
            Sentry.captureException(error, { extra: { context: 'saveJobApplication', bbCodeVersion } });
            showNotification('Erreur lors de l\'enregistrement de la candidature.', 'error');
            return { success: false };
        }
    }, [applicant, staffProfile, bbCodeVersion, formData, getBBCodeContent, filterFormData, selectOptions, showNotification, editingApplication, forgetEditing]);

    // Charge les candidatures du civil connecté ("Mes candidatures").
    const loadMyJobApplications = useCallback(async () => {
        // Un employé sans statut de recrutement interne n'est pas « candidat » (applicant), mais consulte quand même son dossier.
        const ownerUid = applicant?.uid || (staffProfile && currentEmployee?.uid) || null;
        if (!ownerUid) {
            setMyJobApplications([]);
            return;
        }
        setIsLoadingJobApplications(true);
        try {
            const apps = await loadApplicationsOf(ownerUid);
            setMyJobApplications(apps);
        } catch (error) {
            console.error('Error loading job applications:', error);
            Sentry.captureException(error, { extra: { context: 'loadMyJobApplications' } });
        } finally {
            setIsLoadingJobApplications(false);
        }
    }, [applicant, staffProfile, currentEmployee]);

    // Démarre la modification d'une candidature : relit son état en base (elle a pu changer depuis l'affichage), recharge ses réponses
    // dans le bon formulaire et lie les enregistrements suivants à CETTE candidature. Retourne true si le mode édition est actif.
    const startEditingApplication = useCallback(async (application, { resumed = false } = {}) => {
        if (!applicant?.uid || !application?.id) return false;
        try {
            const fresh = await loadApplication(applicant.uid, application.id);
            if (!fresh) { showNotification('Candidature introuvable.', 'error'); forgetEditing(); return false; }
            if (!APPLICATION_EDITABLE_STATUSES.includes(fresh.statut)) {
                showNotification(
                    fresh.statut === 'entretien_programme' || fresh.statut === 'entretien_effectue'
                        ? "Un entretien est prévu : la candidature ne peut plus être modifiée. Écrivez au recrutement depuis « Mon dossier candidat » si besoin."
                        : 'Cette candidature ne peut plus être modifiée.',
                    'warning', 8000
                );
                forgetEditing();
                return false;
            }
            const version = Number(fresh.versionBBCode);
            if (!version || !getFormDefinition(version)?.FieldComponent || !fresh.donnees || Object.keys(fresh.donnees).length === 0) {
                showNotification("Cette candidature a été enregistrée sans ses réponses : elle ne peut pas être modifiée. Refaites-la depuis le formulaire.", 'warning', 8000);
                forgetEditing();
                return false;
            }
            const poste = positionLabelFor(selectOptions, version, fresh.posteCle || fresh.poste) || fresh.poste || '';
            setPendingFormLoad({ version, data: { ...fresh.donnees }, label: poste || 'Candidature' });
            const next = { candidatUid: applicant.uid, id: fresh.id, version, poste, statut: fresh.statut };
            setEditingApplication(next);
            try { localStorage.setItem(EDIT_STORAGE_KEY, JSON.stringify({ uid: applicant.uid, id: fresh.id })); } catch (error) { /* ignoré */ }
            if (resumed) showNotification(`Modification de votre candidature « ${poste} » reprise : le dernier enregistrement a été rechargé.`, 'info-circle', 6000);
            return true;
        } catch (error) {
            console.error('startEditingApplication', error);
            showNotification("Impossible de démarrer la modification de la candidature.", 'error');
            return false;
        }
    }, [applicant, selectOptions, showNotification, forgetEditing]); // eslint-disable-line react-hooks/exhaustive-deps

    const cancelEditingApplication = useCallback(() => {
        forgetEditing();
        showNotification('Modification annulée : la candidature enregistrée n\'a pas changé.', 'info-circle');
    }, [forgetEditing, showNotification]);

    // Reprise après rechargement de la page : si une modification était en cours pour ce compte, on la relance (si la candidature est
    // encore modifiable). Une seule tentative par compte.
    const resumedFor = useRef(null);
    useEffect(() => {
        if (!applicant?.uid || editingApplication || resumedFor.current === applicant.uid) return;
        resumedFor.current = applicant.uid;
        let stored = null;
        try { stored = JSON.parse(localStorage.getItem(EDIT_STORAGE_KEY) || 'null'); } catch (error) { stored = null; }
        if (stored?.uid === applicant.uid && stored.id) startEditingApplication({ id: stored.id }, { resumed: true });
        else if (stored) forgetEditing();
    }, [applicant?.uid]); // eslint-disable-line react-hooks/exhaustive-deps

    // Se déconnecter (ou changer de compte) abandonne la modification.
    useEffect(() => {
        if (!applicant?.uid && editingApplication) forgetEditing();
    }, [applicant?.uid, editingApplication, forgetEditing]);

    // Changer de formulaire pendant la modification l'abandonne (une candidature ne change pas de formulaire) — sauf pendant le chargement initial.
    useEffect(() => {
        if (editingApplication && !pendingFormLoad && Number(bbCodeVersion) !== Number(editingApplication.version)) {
            forgetEditing();
            showNotification('Modification abandonnée : vous avez changé de formulaire. La candidature enregistrée n\'a pas changé.', 'warning', 7000);
        }
    }, [bbCodeVersion, pendingFormLoad, editingApplication, forgetEditing, showNotification]);

    // « Recharger » une candidature de « Mes candidatures » : même mécanisme que le chargement d'un rapport
    // (bascule sur le bon formulaire de candidature puis le remplit avec ses réponses enregistrées).
    const loadApplicationIntoForm = useCallback((application) => {
        const version = Number(application?.versionBBCode);
        if (!version || !getFormDefinition(version)?.FieldComponent || !application?.donnees) {
            showNotification('Cette candidature ne peut pas être rechargée (aucune réponse enregistrée).', 'warning');
            return false;
        }
        setPendingFormLoad({
            version,
            data: { ...application.donnees },
            label: application.poste || 'Candidature',
        });
        return true;
    }, [showNotification]);

    // Transition de statut générique, utilisée aussi bien par le civil
    // (Mettre en pause / Retirer / Candidater depuis "saved") que par le
    // panneau admin (Planifier un entretien / Marquer effectué / Accepter /
    // Refuser) — voir PendingJobApplications.js. extra permet de fusionner des
    // champs additionnels (ex: interviewDateTime) en même temps que le statut.
    const updateJobApplicationStatus = useCallback(async (applicantUid, applicationId, newStatus, extra = {}) => {
        if (!applicantUid || !applicationId || !newStatus) return { success: false };
        try {
            const existing = await loadApplication(applicantUid, applicationId);
            if (!existing) {
                showNotification('Candidature introuvable.', 'error');
                return { success: false };
            }
            const statut = normalizeApplicationStatus(newStatus);
            // Reprendre une candidature en pause la rend active : le plafond s'applique (seulement quand c'est le candidat lui-même qui agit).
            if (statut === 'soumise' && normalizeApplicationStatus(existing.statut) === 'en_pause' && applicantUid === auth.currentUser?.uid) {
                const activeCount = countActiveApplications(await loadApplicationsOf(applicantUid));
                if (activeCount >= maxActiveApplications(!!existing.interne)) {
                    showNotification(applicationLimitMessage(activeCount, !!existing.interne), 'warning', 10000);
                    return { success: false };
                }
            }
            // Candidater / reprendre un brouillon ou une candidature en pause : mêmes conditions qu'un envoi depuis le formulaire.
            if (statut === 'soumise' && ['brouillon', 'en_pause'].includes(existing.statut)) {
                if (!existing.donnees || Object.keys(existing.donnees).length === 0) {
                    showNotification('Cette candidature a été enregistrée sans ses réponses : rouvrez le formulaire, remplissez-le puis candidatez depuis le formulaire.', 'exclamation-circle', 10000);
                    return { success: false };
                }
                const check = validateApplication(existing.versionBBCode, { ...existing.donnees, recruitmentPosition: existing.donnees.recruitmentPosition || existing.posteCle }, { mode: 'submit', existing, selectOptions });
                if (check.errors.length > 0) {
                    showNotification(formatIssues(check.errors, { title: 'Candidature incomplète :' }), 'exclamation-circle', 10000);
                    return { success: false };
                }
            }
            const historique = existing.historique ? [...existing.historique] : [];
            historique.push({ statut, horodatage: Date.now() });
            const updated = sanitizeForFirebase({
                ...existing,
                ...extra,
                statut,
                modifieLe: Date.now(),
                historique,
            });
            await saveApplication(applicantUid, applicationId, updated);
            if (statut === 'soumise') notifyGroup('recrutement', { type: 'recrutement', titre: `Candidature (re)soumise : ${existing.poste || 'poste'}`, texte: existing.nomCandidat || undefined, lien: { cible: 'recrutement' } });
            logActivity({
                category: 'recrutement', action: 'application_status_changed', severity: statut === 'retiree' ? 'warning' : 'info',
                summary: `Candidature « ${applicationStatusLabel(statut)} » : ${existing.nomCandidat || applicantUid} — ${existing.poste || 'poste inconnu'}`,
                details: `Ancien statut : ${applicationStatusLabel(existing.statut)}\nIdentifiant : ${applicationId}`, target: existing.nomCandidat || undefined,
            });
            return { success: true, application: { ...updated, id: applicationId } };
        } catch (error) {
            console.error('Error updating job application status:', error);
            if (error?.code === 'lockdown') { showNotification(LOCK_MESSAGE, 'warning'); return { success: false }; }
            Sentry.captureException(error, { extra: { context: 'updateJobApplicationStatus', applicantUid, applicationId, newStatus } });
            showNotification('Erreur lors de la mise à jour de la candidature.', 'error');
            return { success: false };
        }
    }, [showNotification, selectOptions]);

    const showRareEasterEggDirectly = useCallback(() => {
        setShowEasterEggModal(true);
        setEasterEggType('rare');
        // Send webhook only if on localhost for the manual trigger
        if (window.location.hostname === 'localhost') {
            sendEasterEggNotification('rare'); // Pass 'rare' type
        }
    }, [sendEasterEggNotification, setEasterEggType, setShowEasterEggModal]);

    // N'exige plus qu'un nom d'employé/patient soit sélectionné dans le
    // formulaire courant : la fenêtre "Rapports enregistrés" s'ouvre toujours,
    // et c'est SavedReportsModal (via useEmployeeAuth) qui décide quoi montrer
    // — ses propres rapports si un employé est connecté, un sélecteur si
    // admin, ou un message de blocage si personne n'est connecté.
    const toggleSavedReports = useCallback((rawFilterVersions = null, rawEmployeeType = null, rawCallback = null) => {
        // Utilisé aussi directement comme onClick : on ignore tout argument qui n'est pas du bon type
        // (le 1er argument est alors l'événement du clic, pas un filtre).
        const filterVersions = Array.isArray(rawFilterVersions) ? rawFilterVersions : null;
        const employeeType = typeof rawEmployeeType === 'string' ? rawEmployeeType : null;
        const callback = typeof rawCallback === 'function' ? rawCallback : null;
        if (showSavedReports) {
            setShowSavedReports(false);
            setPreselectedEmployeeType(null);
            setReportSelectionFilter(null);
            pendingReportAttachmentCallback.current = null;

            return;
        }

        setShowSavedReports(true);
        setPreselectedEmployeeType(employeeType);
        setReportSelectionFilter(filterVersions);
        pendingReportAttachmentCallback.current = callback;
    }, [setPreselectedEmployeeType, setReportSelectionFilter, setShowSavedReports, showSavedReports]);

    const handleShowPositionInfo = useCallback((positionKey, recruitmentDataSource = null) => {
        let data = null;

        if (!positionKey) {
            showNotification("Veuillez sélectionner un poste d'abord.", 'warning');
            return;
        }

        if (recruitmentDataSource && typeof recruitmentDataSource === 'object') {
            data = recruitmentDataSource[positionKey];
        }

        if (data) {
            setCurrentPositionInfo(data);
            setShowPositionInfoModal(true);
        } else {
            showNotification("Aucune information détaillée n'est disponible pour ce poste.", 'warning');
        }
    }, [showNotification]);

    return {
        saveReport,
        savedReports,
        setSavedReports,
        showSavedReports,
        setShowSavedReports,
        isLoadingUserReports,
        setIsLoadingUserReports,
        selectedUserForSavedReports,
        setSelectedUserForSavedReports,
        preselectedEmployeeType,
        setPreselectedEmployeeType,
        loadUserSavedReports,
        loadReportForUser,
        handleReportSelectedForAttachment,
        onAttachReportSummaryRequest,
        deleteReportsForUser,
        loadSharedReportsForPatient,
        loadCivilianDossier,
        shareReportWithPatient,
        copyReportToOwnAccount,
        saveJobApplication,
        loadMyJobApplications,
        loadApplicationIntoForm,
        editingApplication,
        startEditingApplication,
        cancelEditingApplication,
        updateJobApplicationStatus,
        myJobApplications,
        isLoadingJobApplications,
        showMyJobApplications,
        setShowMyJobApplications,
        showRareEasterEggDirectly,
        toggleSavedReports,
        showPositionInfoModal,
        setShowPositionInfoModal,
        currentPositionInfo,
        setCurrentPositionInfo,
        handleShowPositionInfo,
        pendingReportAttachmentCallback,
        reportSelectionFilter,
        setReportSelectionFilter
    };
};